    ('organizaciones', (select count(*)::int from core.organization where slug = 'demo-cadena'), 1),
    ('sucursales', (select count(*)::int from core.property x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 6),
    ('productos', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 289),
    ('precios_por_sucursal', (select count(*)::int from restaurantes.branch_products bp join core.property p on p.id = bp.property_id join core.organization o on o.id = p.organization_id where o.slug = 'demo-cadena'), 1666),
    ('productos_alcohol_sin_domicilio', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and x.no_domicilio), 33),
    ('promociones', (select count(*)::int from restaurantes.promotions x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 5),
    ('zonas_de_reparto', (select count(*)::int from restaurantes.known_zone x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 101),
    ('conocimiento_publicado', (select count(*)::int from restaurantes.conocimiento_negocio x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and x.estado = 'publicado'), 22),
    ('voz_deshabilitada', (select count(*)::int from restaurantes.branch_voice_config x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and not x.habilitado), 6)
) as m(metrica, obtenido, esperado);
