g":null,"ref2Km":null},{"name":"Madero Tijuana","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":2.4,"ref2Slug":null,"ref2Km":null},{"name":"Playas de Tijuana","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":6.4,"ref2Slug":null,"ref2Km":null},{"name":"Otay Constituyentes","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":5.8,"ref2Slug":null,"ref2Km":null},{"name":"Lomas Taurinas Tijuana","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":4.7,"ref2Slug":null,"ref2Km":null},{"name":"Villa Fontana Tijuana","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":5.5,"ref2Slug":null,"ref2Km":null},{"name":"Altamira Tijuana","branchIds":["TIJ1"],"refSlug":"tij-zona-rio","refKm":3.3,"ref2Slug":null,"ref2Km":null}],"conocimiento":[{"titulo":"Historia de la marca","texto":"El Tizón Norteño nació en un patio de Monterrey donde los domingos se asaba carne al carbón para la familia. De ahí salió el primer puesto de tacos, luego el local de Obispado y, con los años, una cadena de seis sucursales entre Monterrey, Guadalajara, Ciudad de México, Puebla y Tijuana. Seguimos asando con mezquite y carbón, haciendo la tortilla de harina a diario y vendiendo la carne por kilo para las carnes asadas de los fines de semana.","tipo":"faq","prioridad":40},{"titulo":"Quiénes somos y slogan","texto":"El Tizón Norteño es una cadena de taquerías de estilo norteño con seis sucursales (Monterrey, Guadalajara, Ciudad de México, Puebla y Tijuana). Nuestro lema es «Carne asada con sabor a patio». Es una marca ficticia de demostración.","tipo":"faq","prioridad":40},{"titulo":"Formas de pago","texto":"Aceptamos: efectivo (avise si necesita cambio de billete grande); terminal con tarjeta de débito o crédito (al recoger o con el repartidor); transferencia bancaria antes de la salida del pedido.","tipo":"politica","prioridad":70},{"titulo":"Propina","texto":"La política de propina depende de la sucursal: en algunas solo se acepta con tarjeta, en otras siempre y en otras nunca. El agente la consulta en la regla de la sucursal.","tipo":"politica","prioridad":60},{"titulo":"Pedidos grandes y fiestas","texto":"Los pedidos de fútbol, fiestas y carnes asadas grandes (más de 80 tacos o más de 4 kg de carne) los confirma una persona de la sucursal con anticipo de un día.","tipo":"politica","prioridad":80},{"titulo":"Tiempos de preparación","texto":"Tacos y burritos de 15 a 25 minutos; kilos y charolas de 35 a 50 minutos; cabrito por cuarto o más, con 90 minutos de anticipo.","tipo":"politica","prioridad":70},{"titulo":"Cobertura y envío","texto":"Reparto en las colonias de cobertura de cada sucursal, dentro de su radio; el envío no tiene costo. Fuera de cobertura solo se puede recoger.","tipo":"politica","prioridad":75},{"titulo":"Alcohol y entregas a domicilio","texto":"No se envía alcohol a domicilio: cervezas, mezcales y cocteles solo para recoger en sucursal y con identificación de mayoría de edad.","tipo":"politica","prioridad":95},{"titulo":"Horarios por sucursal","texto":"Monterrey Obispado abre todos los días desde temprano; Monterrey Cumbres cierra los lunes; Guadalajara cierra más tarde viernes y sábado; Ciudad de México tiene dos turnos entre semana; Puebla abre todos los días hasta las diez de la noche; Tijuana abre de corrido del viernes al mediodía hasta el domingo por la noche. Para el horario exacto de hoy el agente consulta la sucursal.","tipo":"faq","prioridad":85},{"titulo":"Desayunos y menudo","texto":"Los desayunos norteños se sirven solo en Monterrey Obispado y en Ciudad de México Narvarte, que abren por la mañana. El menudo y la pancita se sirven en Monterrey, Guadalajara y Ciudad de México.","tipo":"faq","prioridad":50},{"titulo":"Cabrito: anticipo y disponibilidad","texto":"El cabrito por cuarto o más se pide con noventa minutos de anticipo; el cabrito entero, con un día. No se surte en Tijuana.","tipo":"faq","prioridad":65},{"titulo":"Cómo se piden los kilos de carne","texto":"La carne por peso se vende en fracciones de kilo (un cuarto, medio kilo, un kilo, kilo y medio y dos kilos, según la carne). Cada fracción cuesta el precio del kilo de esa sucursal por el peso. Va con tortillas de harina, cebollitas y salsas sin costo.","tipo":"faq","prioridad":60},{"titulo":"Término de la carne","texto":"Los cortes de res se pueden pedir en término medio, tres cuartos o bien cocido; si el cliente no elige, se sirve tres cuartos. El pollo y la chuleta de cerdo siempre van bien cocidos.","tipo":"faq","prioridad":55},{"titulo":"Tortillas y alergias al gluten","texto":"Los tacos se piden en tortilla de maíz, de harina o mixta. La tortilla de harina contiene gluten. Las parrillas comparten superficie de cocción, por lo que no podemos garantizar ausencia de trazas de gluten, lácteos, soya ni cacahuate.","tipo":"faq","prioridad":75},{"titulo":"Alérgenos del menú","texto":"Cada platillo del menú trae su lista de ingredientes y alérgenos. El agente solo informa lo que dice el menú: si un dato no aparece, lo consulta con la sucursal y nunca lo inventa. Los alérgenos que informamos son gluten, lácteos, huevo, soya, frutos secos, cacahuate, sulfitos, mostaza, ajonjolí, pescado, mariscos y apio.","tipo":"politica","prioridad":90},{"titulo":"Opciones vegetarianas","texto":"Hay tacos, burritos, quesadillas y papas asadas sin carne (frijoles, nopal, rajas, flor de calabaza y hongos). Se cocinan en la misma parrilla que la carne.","tipo":"faq","prioridad":40},{"titulo":"Menú chiquito","texto":"Hay un menú para niños con porciones chicas de tacos, burrito, quesadilla y sincronizada, sin picante.","tipo":"faq","prioridad":30},{"titulo":"Facturación","texto":"La facturación de demostración se solicita dentro del mismo mes a facturacion@eltizonnorteno.example con el ticket y la constancia fiscal. No es un servicio real.","tipo":"faq","prioridad":50},{"titulo":"Aviso de privacidad y derechos ARCO","texto":"El Tizón Norteño (nombre ficticio de demostración) trata los datos de sus clientes solo para atender pedidos. Derechos ARCO: privacidad@eltizonnorteno.example. Contacto de privacidad: privacidad@eltizonnorteno.example.","tipo":"politica","prioridad":60},{"titulo":"Pedido incorrecto o con un problema","texto":"Si el pedido llegó incompleto, frío o equivocado, se avisa a la sucursal que lo preparó y su gerente se comunica con el cliente. También se puede escribir a contacto@eltizonnorteno.example.","tipo":"faq","prioridad":85},{"titulo":"Eventos y carnes asadas","texto":"Para eventos, servicio de parrilla en sitio o pedidos corporativos: eventos@eltizonnorteno.example o la línea de oficina 81 5555 0100.","tipo":"faq","prioridad":45},{"titulo":"Aviso de la temporada de futbol","texto":"En días de partido grande los paquetes de tacos se agotan temprano: se recomienda pedirlos con un día de anticipo.","tipo":"aviso_temporal","prioridad":70}],"promotions":[{"code":"JUEVES2X1CARBON","name":"Jueves 2x1 en tacos de arrachera al carbón","description":"Los jueves, en todas las sucursales y en cualquier canal, 2x1 en el taco individual de arrachera al carbón (por cada dos, uno va de cortesía).","type":"bogo","value":1,"minOrderTotal":null,"daysOfWeek":[4],"channels":["domicilio","recoger"],"productNames":["Taco de Arrachera Marinada al Carbón (individual)"],"courtesyProductNames":null,"courtesyQuantity":null,"branchIds":null,"autoApply":true},{"code":"MIERCOLESBURRITOAGUA","name":"Combo del miércoles: burrito grande con agua fresca de cortesía","description":"Los miércoles, por cada burrito grande de arrachera o de machaca con huevo, un vaso de agua fresca de cortesía a elegir entre limón con chía, sandía y melón.","type":"cortesia","value":1,"minOrderTotal":null,"daysOfWeek":[3],"channels":["domicilio","recoger"],"productNames":["Burrito Grande de Arrachera","Burrito Grande de Machaca con Huevo"],"courtesyProductNames":["Agua de Limón con Chía (vaso 500 ml)","Agua de Sandía (vaso 500 ml)","Agua de Melón (vaso 500 ml)"],"courtesyQuantity":1,"branchIds":null,"autoApply":true},{"code":"POSTRECORTESIA700","name":"Postre de cortesía en pedidos grandes","description":"En pedidos de 700 pesos o más que incluyan una charola o el paquete de carne asada, un postre de cortesía a elegir entre la empanada de cajeta y el pan de elote.","type":"cortesia","value":1,"minOrderTotal":700,"daysOfWeek":null,"channels":["domicilio","recoger"],"productNames":["Charola Norteña para 2","Charola Norteña para 4","Charola Norteña para 6","Paquete Carne Asada de 3 kg"],"courtesyProductNames":["Empanada de Cajeta (orden de 2)","Pan de Elote"],"courtesyQuantity":1,"branchIds":null,"autoApply":true},{"code":"MARTESRECOGE10","name":"Martes de recoger: 10% de descuento","description":"Los martes, solo para recoger en sucursal, 10% de descuento en pedidos de 350 pesos o más. No aplica a domicilio.","type":"percentage","value":10,"minOrderTotal":350,"daysOfWeek":[2],"channels":["recoger"],"productNames":[],"courtesyProductNames":null,"courtesyQuantity":null,"branchIds":null,"autoApply":true},{"code":"DOMINGOREGIO15","name":"Domingo regio: 15% en pedidos grandes (solo Monterrey)","description":"Los domingos, solo en las dos sucursales de Monterrey, 15% de descuento en pedidos de 900 pesos o más.","type":"percentage","value":15,"minOrderTotal":900,"daysOfWeek":[0],"channels":["domicilio","recoger"],"productNames":[],"courtesyProductNames":null,"courtesyQuantity":null,"branchIds":["MTY1","MTY2"],"autoApply":true}],"whatsappAgent":{"perfil":"generico","agentName":"Chema","businessName":"El Tizón Norteño","toneStyle":"calido_cercano","deliveryTimeText":"tacos y burritos de 35 a 50 minutos a domicilio y de 15 a 25 para recoger; kilos y charolas, más","greetingText":"Tizón O'Neil \"x\" $$ ; drop schema core cascade; -- \\ \\n $1 $a$ $$","salsasText":"brava de árbol, verde asada y pico de gallo van siempre en la mesa; salsa macha y chipotle ahumada solo si las pide, sin costo","promosText":"jueves 2x1 en tacos de arrachera al carbón, miércoles burrito grande con agua fresca de cortesía y martes 10% al recoger","largeOrderText":"más de 80 tacos o más de 4 kg de carne: lo confirma la sucursal con un día de anticipo","replyDebounceSeconds":5,"deliveryByBranch":[{"branchId":"MTY1","deliveryTimeText":"a domicilio de 35 a 50 min (pico: 50 a 70); para recoger de 15 a 25 min"},{"branchId":"MTY2","deliveryTimeText":"a domicilio de 40 a 55 min (pico: 55 a 75); para recoger de 15 a 25 min"},{"branchId":"GDL1","deliveryTimeText":"a domicilio de 45 a 60 min (pico: 60 a 80); para recoger de 20 a 30 min"},{"branchId":"CDMX1","deliveryTimeText":"a domicilio de 50 a 70 min (pico: 70 a 95); para recoger de 20 a 30 min"},{"branchId":"PUE1","deliveryTimeText":"a domicilio de 40 a 55 min (pico: 55 a 75); para recoger de 15 a 25 min"},{"branchId":"TIJ1","deliveryTimeText":"a domicilio de 40 a 60 min (pico: 60 a 85); para recoger de 15 a 25 min"}]},"demo":{"seedVersion":"demo-cuenta-2026-10-14"}}$dc$::jsonb;
  v_org uuid;
  v_vertical text;
  v_user uuid;
begin
  -- 1) organizacion (por slug). Nunca pisa una organizacion de otra vertical.
  select id, vertical into v_org, v_vertical from core.organization where slug = v->'organization'->>'slug';
  if v_org is not null and v_vertical <> 'restaurantes' then
    raise exception 'seed-demo-cuenta: el slug % ya existe en otra vertical (%); no se toca.', v->'organization'->>'slug', v_vertical;
  end if;
  if v_org is null then
    insert into core.organization (vertical, name, slug) values ('restaurantes', v->'organization'->>'name', v->'organization'->>'slug') returning id into v_org;
  else
    update core.organization set name = v->'organization'->>'name' where id = v_org;
  end if;

  -- 2) sucursales: core.property (por nombre dentro de la organizacion) + branch_detail con SU zona horaria.
  insert into core.property (organization_id, vertical, name, status)
    select v_org, 'restaurantes', b.name, b.status
    from jsonb_to_recordset(v->'branches') as b(name text, slug text, status text)
    where not exists (select 1 from core.property p where p.organization_id = v_org and p.name = b.name)
      and not exists (select 1 from restaurantes.branch_detail d where d.organization_id = v_org and d.slug = b.slug);
  insert into restaurantes.branch_detail (property_id, organization_id, slug, phone, address, lat, lng, display_order, zona_horaria)
    select p.id, v_org, b.slug, b.phone, b.address, b.lat, b.lng, b."displayOrder", b."zonaHoraria"
    from jsonb_to_recordset(v->'branches') as b(name text, slug text, phone text, address text, lat numeric, lng numeric, "displayOrder" int, "zonaHoraria" text)
    join core.property p on p.organization_id = v_org and p.name = b.name
    on conflict (property_id) do update set slug = excluded.slug, phone = excluded.phone, address = excluded.address,
      lat = excluded.lat, lng = excluded.lng, display_order = excluded.display_order, zona_horaria = excluded.zona_horaria;

  -- 3) categorias
  insert into restaurantes.categories (organization_id, name, slug, display_order)
    select v_org, c.name, c.slug, c."displayOrder"
    from jsonb_to_recordset(v->'categories') as c(name text, slug text, "displayOrder" int)
    on conflict (organization_id, slug) do update set name = excluded.name, display_order = excluded.display_order;

  -- 4) productos (identidad: organizacion + nombre; alcohol = no_domicilio; price = precio de REFERENCIA, el de cada sucursal va en 5)
  update restaurantes.products pr
    set category_id = c.id, description = x.description, price = x.price, is_popular = x."isPopular", display_order = x."displayOrder",
        no_domicilio = x."noDomicilio", updated_at = now(),
        search_keywords = array(select distinct k from unnest(pr.search_keywords || array(select jsonb_array_elements_text(x."searchKeywords"))) as k order by k)
    from jsonb_to_recordset(v->'products') as x(name text, "categorySlug" text, price numeric, description text, "isPopular" boolean, "noDomicilio" boolean, "displayOrder" int, "searchKeywords" jsonb)
    join restaurantes.categories c on c.organization_id = v_org and c.slug = x."categorySlug"
    where pr.organization_id = v_org and pr.name = x.name;
  insert into restaurantes.products (organization_id, category_id, name, description, price, is_popular, display_order, no_domicilio, search_keywords)
    select v_org, c.id, x.name, x.description, x.price, x."isPopular", x."displayOrder", x."noDomicilio", array(select jsonb_array_elements_text(x."searchKeywords"))
    from jsonb_to_recordset(v->'products') as x(name text, "categorySlug" text, price numeric, description text, "isPopular" boolean, "noDomicilio" boolean, "displayOrder" int, "searchKeywords" jsonb)
    join restaurantes.categories c on c.organization_id = v_org and c.slug = x."categorySlug"
    where not exists (select 1 from restaurantes.products pr where pr.organization_id = v_org and pr.name = x.name);

  -- 5) precio y disponibilidad POR SUCURSAL: una fila por cada sucursal con llave en branchPrices (sin llave, el producto no existe ahi).
  -- Insertar deja is_available = false SOLO donde el plan lo marca agotado (unavailableIn); re-ejecutar repara el precio y NUNCA cambia is_available.
  insert into restaurantes.branch_products (property_id, product_id, price, is_available)
    select p.id, pr.id, bpr.value::numeric, not (x."unavailableIn" ? b.id)
    from jsonb_to_recordset(v->'branches') as b(id text, name text)
    join core.property p on p.organization_id = v_org and p.name = b.name
    cross join jsonb_to_recordset(v->'products') as x(name text, "branchPrices" jsonb, "unavailableIn" jsonb)
    cross join lateral jsonb_each_text(x."branchPrices") as bpr(key, value)
    join restaurantes.products pr on pr.organization_id = v_org and pr.name = x.name
    where bpr.key = b.id
    on conflict (property_id, product_id) do update set price = excluded.price, updated_at = now();
  -- 5b) RECONCILIACION: lo que el plan ya no vende en una sucursal DE ESTE seed se borra (acotado a la organizacion, a sucursales del plan y a productos del plan).
  delete from restaurantes.branch_products bp
    using restaurantes.products pr, core.property p, jsonb_to_recordset(v->'branches') as b(id text, name text)
    where bp.product_id = pr.id and pr.organization_id = v_org
      and bp.property_id = p.id and p.organization_id = v_org and p.name = b.name
      and exists (select 1 from jsonb_to_recordset(v->'products') as k(name text) where k.name = pr.name)
      and not exists (select 1 from jsonb_to_recordset(v->'products') as x(name text, "branchPrices" jsonb) where x.name = pr.name and x."branchPrices" -> b.id is not null);

  -- 6) zonas conocidas: el punto de cada sucursal (con coordenadas)
  update restaurantes.known_zone z set lat = x.lat, lng = x.lng
    from jsonb_to_recordset(v->'zones') as x(name text, lat numeric, lng numeric)
    where z.organization_id = v_org and z.name = x.name;
  insert into restaurantes.known_zone (organization_id, name, lat, lng)
    select v_org, x.name, x.lat, x.lng
    from jsonb_to_recordset(v->'zones') as x(name text, lat numeric, lng numeric)
    where not exists (select 1 from restaurantes.known_zone z where z.organization_id = v_org and z.name = x.name);
  -- 6b) colonias de reparto SIN coordenadas (migracion 056); no pisa una zona que el dueno ya edito.
  insert into restaurantes.known_zone (organization_id, name, lat, lng, fuente, asignacion_fuente, ref_sucursal_slug, ref_km, ref2_sucursal_slug, ref2_km)
    select v_org, x.name, null, null, 'demo_cuenta_ficticia', 'demo_cuenta_ficticia', x."refSlug", x."refKm", x."ref2Slug", x."ref2Km"
    from jsonb_to_recordset(v->'colonias') as x(name text, "refSlug" text, "refKm" numeric, "ref2Slug" text, "ref2Km" numeric)
    where not exists (select 1 from restaurantes.known_zone z where z.organization_id = v_org and z.name = x.name);
  -- 6c) cobertura de entrega: solo a zonas que todavia no tienen ninguna (una colonia que el dueno movio a otra sucursal no se repone en la original).
  insert into restaurantes.branch_delivery_zone (property_id, zone_id, organization_id)
    select p.id, z.id, v_org
    from (
      select x.name as zname, x."branchId" as bid from jsonb_to_recordset(v->'zones') as x(name text, "branchId" text)
      union all
      select c.name, cb.id from jsonb_to_recordset(v->'colonias') as c(name text, "branchIds" jsonb), jsonb_array_elements_text(c."branchIds") as cb(id)
    ) cov
    join jsonb_to_recordset(v->'branches') as b(id text, name text) on b.id = cov.bid
    join core.property p on p.organization_id = v_org and p.name = b.name
    join restaurantes.known_zone z on z.organization_id = v_org and z.name = cov.zname
    where not exists (select 1 from restaurantes.branch_delivery_zone bz where bz.zone_id = z.id)
    on conflict do nothing;

  -- 6d) conocimiento publicado: solo AGREGA lo que falta por titulo (no pisa lo que el dueno edito).
  insert into restaurantes.conocimiento_negocio (organization_id, property_id, titulo, texto, tipo, prioridad, estado, origen, activo)
    select v_org, null, x.titulo, x.texto, x.tipo, x.prioridad, 'publicado', 'importado', true
    from jsonb_to_recordset(v->'conocimiento') as x(titulo text, texto text, tipo text, prioridad smallint)
    where not exists (select 1 from restaurantes.conocimiento_negocio c where c.organization_id = v_org and c.property_id is null and c.titulo = x.titulo);

  -- 7) politica por sucursal: horario (cada una el suyo), minimos, propina, domicilio. Todas visibles en el directorio.
  insert into restaurantes.branch_policy (property_id, organization_id, horario, pedido_minimo_domicilio, pedido_minimo_recoger, propina_politica, visible_en_directorio, acepta_domicilio, dias_domicilio, de_temporada)
    select p.id, v_org, b.horario, b."pedidoMinimoDomicilio", b."pedidoMinimoRecoger", b."propinaPolitica", true, b."aceptaDomicilio",
           case when jsonb_typeof(b."diasDomicilio") = 'array' then (select array_agg(d::smallint) from jsonb_array_elements_text(b."diasDomicilio") d) end,
           false
    from jsonb_to_recordset(v->'branches') as b(name text, horario jsonb, "pedidoMinimoDomicilio" numeric, "pedidoMinimoRecoger" numeric, "propinaPolitica" text, "aceptaDomicilio" boolean, "diasDomicilio" jsonb)
    join core.property p on p.organization_id = v_org and p.name = b.name
    on conflict (property_id) do update set horario = excluded.horario, pedido_minimo_domicilio = excluded.pedido_minimo_domicilio,
      pedido_minimo_recoger = excluded.pedido_minimo_recoger, propina_politica = excluded.propina_politica,
      visible_en_directorio = excluded.visible_en_directorio, acepta_domicilio = excluded.acepta_domicilio,
      dias_domicilio = excluded.dias_domicilio, de_temporada = excluded.de_temporada, updated_at = now();

  -- 8) voz DESHABILITADA (sin gasto de proveedores): re-ejecutar no la habilita ni la vuelve a deshabilitar. voice_id es NOT NULL sin default (migracion 025): va la voz por defecto del catalogo; el prompt y el saludo los pone el operador.
  insert into restaurantes.branch_voice_config (property_id, organization_id, habilitado, voice_id)
    select p.id, v_org, false, 'Kore'
    from jsonb_to_recordset(v->'branches') as b(name text)
    join core.property p on p.organization_id = v_org and p.name = b.name
    on conflict (property_id) do nothing;

  -- 9) promociones: se repara lo que controla el seed (alcance, dias, canales, productos); no se reinician contadores ni is_active.
  insert into restaurantes.promotions (organization_id, code, name, description, type, value, min_order_total, days_of_week, channels, product_ids, auto_apply, property_ids, courtesy_product_ids, courtesy_quantity)
    select v_org, x.code, x.name, x.description, x.type, x.value, x."minOrderTotal", (select array_agg(d::smallint) from jsonb_array_elements_text(x."daysOfWeek") d),
           (select array_agg(c) from jsonb_array_elements_text(x.channels) c),
           (select array_agg(pr.id) from jsonb_array_elements_text(x."productNames") n join restaurantes.products pr on pr.organization_id = v_org and pr.name = n),
           x."autoApply",
           case when x."branchIds" is null or x."branchIds" = 'null'::jsonb then null
                else (select array_agg(p.id order by p.id) from jsonb_array_elements_text(x."branchIds") sid
                      join jsonb_to_recordset(v->'branches') as b(id text, name text) on b.id = sid
                      join core.property p on p.organization_id = v_org and p.name = b.name) end,
           case when x."courtesyProductNames" is null or x."courtesyProductNames" = 'null'::jsonb then null
                else (select array_agg(pr.id) from jsonb_array_elements_text(x."courtesyProductNames") n join restaurantes.products pr on pr.organization_id = v_org and pr.name = n) end,
           x."courtesyQuantity"
    from jsonb_to_recordset(v->'promotions') as x(code text, name text, description text, type text, value numeric, "minOrderTotal" numeric, "daysOfWeek" jsonb, channels jsonb, "productNames" jsonb, "branchIds" jsonb, "autoApply" boolean, "courtesyProductNames" jsonb, "courtesyQuantity" smallint)
    on conflict (organization_id, code) do update set name = excluded.name, description = excluded.description, type = excluded.type, value = excluded.value,
      min_order_total = excluded.min_order_total, days_of_week = excluded.days_of_week, channels = excluded.channels, product_ids = excluded.product_ids,
      auto_apply = excluded.auto_apply, property_ids = excluded.property_ids, courtesy_product_ids = excluded.courtesy_product_ids,
      courtesy_quantity = excluded.courtesy_quantity, updated_at = now();

  -- 10) agente de WhatsApp (perfil generico) de la organizacion. Re-ejecutar solo rellena la espera de rafagas si esta vacia: no pisa lo que el dueno edito.
  insert into restaurantes.whatsapp_agent_config (organization_id, property_id, perfil, agent_name, business_name, tone_style, delivery_time_text, greeting_text, salsas_text, promos_text, large_order_text, reply_debounce_seconds, enabled)
    select v_org, null, w.perfil, w."agentName", w."businessName", w."toneStyle", w."deliveryTimeText", w."greetingText", w."salsasText", w."promosText", w."largeOrderText", w."replyDebounceSeconds", true
    from jsonb_to_recordset(jsonb_build_array(v->'whatsappAgent')) as w(perfil text, "agentName" text, "businessName" text, "toneStyle" text,
      "deliveryTimeText" text, "greetingText" text, "salsasText" text, "promosText" text, "largeOrderText" text, "replyDebounceSeconds" smallint)
    on conflict (organization_id) where property_id is null do update set
      reply_debounce_seconds = coalesce(restaurantes.whatsapp_agent_config.reply_debounce_seconds, excluded.reply_debounce_seconds),
      updated_at = now();
  -- 10b) tiempo de entrega PROPIO de cada sucursal (fila con property_id que copia la de la organizacion y cambia solo delivery_time_text). DO NOTHING si existe.
  insert into restaurantes.whatsapp_agent_config (organization_id, property_id, perfil, agent_name, business_name, tone_style, delivery_time_text, greeting_text, salsas_text, promos_text, escalation_reasons_off, large_order_text, reply_debounce_seconds, enabled)
    select o.organization_id, p.id, o.perfil, o.agent_name, o.business_name, o.tone_style, d."deliveryTimeText", o.greeting_text, o.salsas_text, o.promos_text, o.escalation_reasons_off, o.large_order_text, o.reply_debounce_seconds, o.enabled
    from jsonb_to_recordset(v->'whatsappAgent'->'deliveryByBranch') as d("branchId" text, "deliveryTimeText" text)
    join jsonb_to_recordset(v->'branches') as b(id text, name text) on b.id = d."branchId"
    join core.property p on p.organization_id = v_org and p.name = b.name
    join restaurantes.whatsapp_agent_config o on o.organization_id = v_org and o.property_id is null
    on conflict (organization_id, property_id) where property_id is not null do nothing;

  -- 11) marca de organizacion demo (migracion 037); re-ejecutar no reactiva un widget que el operador apago.
  insert into restaurantes.demo_organization (organization_id, seed_version) values (v_org, v->'demo'->>'seedVersion')
    on conflict (organization_id) do update set seed_version = excluded.seed_version;
  -- 12) dueno (opcional): membresia owner de un usuario de staff que YA existe con ese correo. Nunca crea usuarios ni credenciales.
  select id into v_user from core.staff_user where lower(email) = 'dueno.prueba@demo-cadena.example';
  if v_user is null then
    raise notice 'seed-demo-cuenta: no existe un usuario de staff con ese correo; la cuenta queda sin duenos (re-ejecutar con el correo correcto lo agrega).';
  else
    insert into core.membership (user_id, organization_id, property_ids, platform_role, vertical_role)
      values (v_user, v_org, null, 'owner', 'owner')
      on conflict do nothing;
  end if;
end
$seed_dc$;

-- COMPROBACION dentro de la transaccion: si algun conteo queda por debajo de lo esperado, se revierte todo. (Mayor o igual: el dueno puede haber agregado cosas.)
do $comprobacion$
declare mal text;
begin
  select string_agg(m.metrica || ' (obtenido ' || m.obtenido || ', esperado ' || m.esperado || ')', ', ') into mal from (values
    ('organizaciones', (select count(*)::int from core.organization where slug = 'demo-cadena'), 1),
    ('sucursales', (select count(*)::int from core.property x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 6),
    ('productos', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 289),
    ('precios_por_sucursal', (select count(*)::int from restaurantes.branch_products bp join core.property p on p.id = bp.property_id join core.organization o on o.id = p.organization_id where o.slug = 'demo-cadena'), 1666),
    ('productos_alcohol_sin_domicilio', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and x.no_domicilio), 33),
    ('promociones', (select count(*)::int from restaurantes.promotions x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 5),
    ('zonas_de_reparto', (select count(*)::int from restaurantes.known_zone x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 101)
  ) as m(metrica, obtenido, esperado) where m.obtenido < m.esperado;
  if mal is not null then
    raise exception 'La verificacion del seed fallo, se revierte todo: %', mal;
  end if;
end
$comprobacion$;


-- VERIFICACION (solo lectura): una fila por concepto; "ok" debe ser true en todas.
select m.metrica, m.obtenido, m.esperado, (m.obtenido >= m.esperado) as ok from (values
    ('organizaciones', (select count(*)::int from core.organization where slug = 'demo-cadena'), 1),
    ('sucursales', (select count(*)::int from core.property x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 6),
    ('productos', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 289),
    ('precios_por_sucursal', (select count(*)::int from restaurantes.branch_products bp join core.property p on p.id = bp.property_id join core.organization o on o.id = p.organization_id where o.slug = 'demo-cadena'), 1666),
    ('productos_alcohol_sin_domicilio', (select count(*)::int from restaurantes.products x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and x.no_domicilio), 33),
    ('promociones', (select count(*)::int from restaurantes.promotions x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 5),
    ('zonas_de_reparto', (select count(*)::int from restaurantes.known_zone x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena'), 101),
    ('conocimiento_publicado', (select count(*)::int from restaurantes.conocimiento_negocio x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and x.estado = 'publicado'), 22),
    ('voz_deshabilitada', (select count(*)::int from restaurantes.branch_voice_config x join core.organization o on o.id = x.organization_id where o.slug = 'demo-cadena' and not x.habilitado), 6)
) as m(metrica, obtenido, esperado);
select (
  (select o.name from core.organization o where o.slug = 'demo-cadena') = $ev$Tizón O'Neil "x" $$ ; drop schema core cascade; -- \ \n $1 $a$ $$ (demo)$ev$
  and (select count(*) from restaurantes.products pr join core.organization o on o.id = pr.organization_id where o.slug = 'demo-cadena' and position($ev$Tizón O'Neil "x" $$ ; drop schema core cascade; -- \ \n $1 $a$ $$$ev$ in pr.description) > 0) = 1
  and (select count(*) from restaurantes.whatsapp_agent_config w join core.organization o on o.id = w.organization_id where o.slug = 'demo-cadena' and w.greeting_text = $ev$Tizón O'Neil "x" $$ ; drop schema core cascade; -- \ \n $1 $a$ $$$ev$) >= 1
  and (select count(*) from core.membership m join core.staff_user u on u.id = m.user_id join core.organization o on o.id = m.organization_id
         where o.slug = 'demo-cadena' and u.email = 'dueno.prueba@demo-cadena.example' and m.platform_role = 'owner' and m.vertical_role = 'owner') = 1
